import java.util.*;
public class finddistance {

    public static void main(String[] args) {
        // TODO Auto-generated method stub
        Scanner sc = new Scanner(System.in);
        int feet = sc.nextInt();
        int yards = feet/3;
        int miles = feet/5280;
        System.out.println(yards);
        System.out.println(miles);

    }

}